package com.kitchenos.connect.ui;
import org.junit.Test;
import static org.junit.Assert.*;
public class HomeFunctionProfileTest {
 @Test public void slowUsesHoursMinutesHeatAndFixedReverseHalf(){HomeFunctionProfile p=HomeFunctionProfile.get("slow");assertTrue(p.intervals);assertEquals(3600,p.minSeconds());assertEquals(28800,p.maxSeconds);assertEquals(37,p.minTemperature);assertEquals(98,p.maxTemperature);for(int t:new int[]{37,90,98})assertEquals("",p.issue(28800,t,-5));for(int[] v:new int[][]{{3599,90,-5},{28860,90,-5},{3661,90,-5},{3600,36,-5},{3600,99,-5},{3600,90,0},{3600,90,5},{3600,90,-10}})assertFalse(p.issue(v[0],v[1],v[2]).isEmpty());}
 @Test public void coverNeverAllowsHeatAbove100OrCutting(){HomeFunctionProfile p=HomeFunctionProfile.get("stir");assertEquals("",p.issue(60,0,-5));assertEquals("",p.issue(7200,100,-10));assertFalse(p.issue(60,101,-5).isEmpty());assertFalse(p.issue(60,100,5).isEmpty());assertFalse(p.issue(60,0,0).isEmpty());}
 @Test public void eggsKeepMotorOffAndTemperatureFixed(){HomeFunctionProfile p=HomeFunctionProfile.get("eggs");assertEquals("",p.issue(480,100,0));assertFalse(p.issue(480,99,0).isEmpty());assertFalse(p.issue(480,100,-5).isEmpty());assertTrue(HomeFunctionProfile.eggSeconds(0)<HomeFunctionProfile.eggSeconds(3));}
 @Test public void riceOnlyAcceptsItsTwoFixedRuns(){HomeFunctionProfile p=HomeFunctionProfile.get("rice");assertEquals(1500,p.seconds);assertEquals(2,p.presets().length);assertEquals(2400,p.presets()[1].seconds);for(HomeFunctionProfile.Preset choice:p.presets())assertEquals("",p.issue(choice.seconds,choice.temperature,choice.speed));for(int[] values:new int[][]{{1200,100,0},{2100,100,0},{1500,99,0},{1500,100,5}})assertFalse(p.issue(values[0],values[1],values[2]).isEmpty());}
 @Test public void fryingRequiresMovementAndFiniteDuration(){HomeFunctionProfile p=HomeFunctionProfile.get("fry");assertEquals("",p.issue(1800,180,-10));for(int[] v:new int[][]{{1801,180,-10},{300,181,-10},{300,140,0},{300,140,10},{300,140,-5}})assertFalse(p.issue(v[0],v[1],v[2]).isEmpty());}
 @Test public void thickeningHasTwoFixedRuns(){HomeFunctionProfile p=HomeFunctionProfile.get("thicken");assertTrue(p.fixedDuration());assertEquals(600,HomeFunctionProfile.thickenSeconds(80));assertEquals(720,HomeFunctionProfile.thickenSeconds(100));assertEquals("",p.issue(600,80,20));assertEquals("",p.issue(720,100,20));for(int[] v:new int[][]{{720,80,20},{600,100,20},{600,90,20},{600,80,30},{600,80,-20}})assertFalse(p.issue(v[0],v[1],v[2]).isEmpty());}
}
